//! R035/08 — Owner-locked live editor multi-tab manager. Kernel-side implementation over actual RamFs/state.
use super::Error;
use crate::batch7_ramfs::{RamFs,CONTENT_MAX};
pub struct Tabs<const N:usize>{owner:u64,paths:[Option<([u8;96],usize,u64)>;N]}impl<const N:usize> Tabs<N>{pub fn new(owner:u64)->Self{Self{owner,paths:[None;N]}}pub fn open<const F:usize>(&mut self,owner:u64,fs:&RamFs<F>,path:&[u8])->Result<usize,Error>{if owner==0||owner!=self.owner{return Err(Error::Denied);}if path.len()>96{return Err(Error::Invalid);}let (revision,_)=fs.metadata(path).map_err(|_|Error::Missing)?;for(i,tab)in self.paths.iter().enumerate(){if let Some((buf,n,_))=tab{if &buf[..*n]==path{return Ok(i);}}}let i=self.paths.iter().position(Option::is_none).ok_or(Error::Full)?;let mut p=[0;96];p[..path.len()].copy_from_slice(path);self.paths[i]=Some((p,path.len(),revision));Ok(i)}pub fn stale<const F:usize>(&self,owner:u64,fs:&RamFs<F>,slot:usize)->Result<bool,Error>{if owner!=self.owner{return Err(Error::Denied);}let(p,n,rev)=self.paths.get(slot).copied().flatten().ok_or(Error::Missing)?;Ok(!fs.metadata(&p[..n]).is_ok_and(|(v,_)|v==rev))}}
#[cfg(test)]mod tests{use super::*;#[test]fn real_workflow_and_failure_guard(){let mut fs=RamFs::<1>::new();fs.replace(b"/p/a",b"a").unwrap();let mut t=Tabs::<2>::new(7);let s=t.open(7,&fs,b"/p/a").unwrap();assert_eq!(t.stale(7,&fs,s),Ok(false));fs.replace(b"/p/a",b"b").unwrap();assert_eq!(t.stale(7,&fs,s),Ok(true));}}
